/**
 * LOD disabled.
 *
 * @type {number}
 * @constant
 */
export const LOD_MODE_DISABLED: number;
/**
 * Range-based LOD (smoothstep between `lodNear` and `lodFar`).
 *
 * @type {number}
 * @constant
 */
export const LOD_MODE_RANGE: number;
/**
 * Exponential density LOD (falls off from `lodNear` with `lodDensity`).
 *
 * @type {number}
 * @constant
 */
export const LOD_MODE_EXP: number;
